import {LitElement,html,css} from 'lit';import {customElement,property,state} from 'lit/decorators.js';import type {CardConfig,Hass} from './types';import {isPaired,pair,unpair} from './device';
@customElement('baby-monitor-kiosk-card-editor') export class Editor extends LitElement{
 @property({attribute:false}) hass?:Hass; @state() config?:CardConfig;
 static styles=css`:host{display:block;padding:16px}.grid{display:grid;gap:12px}label{display:grid;gap:4px}input{padding:8px}.pair{display:flex;gap:8px;align-items:center}button{padding:10px}`;
 setConfig(c:CardConfig){this.config=structuredClone(c)} private set(path:string,v:unknown){if(!this.config)return;const c=structuredClone(this.config) as any;const keys=path.split('.');let o=c;while(keys.length>1){const k=keys.shift()!;o[k]??={};o=o[k]}o[keys[0]]=v;this.config=c;this.dispatchEvent(new CustomEvent('config-changed',{detail:{config:c},bubbles:true,composed:true}))}
 private entity(path:string,label:string,value:string,domains:string[]){return html`<label>${label}<ha-entity-picker .hass=${this.hass} .value=${value} .includeDomains=${domains} allow-custom-entity @value-changed=${(e:CustomEvent)=>this.set(path,e.detail.value)}></ha-entity-picker></label>`}
 render(){const c=this.config;if(!c)return html``;const id=c.id??`${c.camera??c.stream}|${c.sound_sensor}`;const checkbox=(path:string,label:string,value:boolean)=>html`<label><input type=checkbox .checked=${value} @change=${(e:any)=>this.set(path,e.target.checked)}> ${label}</label>`;return html`<div class=grid><label>Naam/ID<input .value=${c.id??''} @change=${(e:any)=>this.set('id',e.target.value)}></label>${this.entity('camera','Camera entity',c.camera??'',['camera'])}<label>go2rtc/WebRTC stream<input .value=${c.stream??''} @change=${(e:any)=>this.set('stream',e.target.value)}></label>${this.entity('sound_sensor','Geluidsensor',c.sound_sensor??'',['sensor','binary_sensor'])}${[['sound_threshold_db','Activeringsgrens dB'],['sound_reset_db','Resetgrens dB'],['trigger_for','Minimale geluidsduur (s)'],['silence_duration','Stiltetijd (s)'],['manual_close_cooldown','Cooldown handmatig sluiten (s)']].map(([k,l])=>html`<label>${l}<input type=number .value=${String((c as any)[k]??'')} @change=${(e:any)=>this.set(k,Number(e.target.value))}></label>`)}${checkbox('preload','Stream voorverwarmen',c.preload!==false)}${checkbox('auto_open','Automatisch openen',c.auto_open!==false)}${checkbox('kiosk.enabled','Kioskmodus',c.kiosk?.enabled!==false)}${checkbox('kiosk.device_bound','Alleen gekoppeld apparaat',c.kiosk?.device_bound!==false)}<label>Toegestane HA-user-ID’s (komma-gescheiden)<input .value=${c.kiosk?.allowed_user_ids?.join(', ')??''} @change=${(e:any)=>this.set('kiosk.allowed_user_ids',e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean))}></label>${checkbox('audio.default_muted','Standaard gedempt',c.audio?.default_muted??false)}${checkbox('audio.remember_state','Audiostatus onthouden',c.audio?.remember_state!==false)}${checkbox('controls.mute','Mute-knop tonen',c.controls?.mute!==false)}${checkbox('controls.close','Sluitknop tonen',c.controls?.close!==false)}${checkbox('controls.volume','Volumeknoppen tonen',c.controls?.volume??false)}${checkbox('controls.brightness','Helderheidsknoppen tonen',c.controls?.brightness??false)}${checkbox('debug','Debugstatus',!!c.debug)}<label>Companion notify service<input .value=${c.companion?.notify_service??''} @change=${(e:any)=>this.set('companion.notify_service',e.target.value)}></label>${[['active_brightness','Actieve helderheid'],['idle_brightness','Rusthelderheid'],['active_volume','Actief volume'],['idle_volume','Rustvolume']].map(([k,l])=>html`<label>${l}<input type=number min=0 max=100 .value=${String((c.companion as any)?.[k]??'')} @change=${(e:any)=>this.set(`companion.${k}`,Number(e.target.value))}></label>`)}<div class=pair><b>Dit apparaat gekoppeld: ${isPaired(id)?'ja':'nee'}</b><button @click=${()=>{isPaired(id)?unpair(id):pair(id);this.requestUpdate()}}>${isPaired(id)?'Ontkoppel':'Koppel dit apparaat'}</button></div></div>`}
}
